use crate::position::AccountBalance;
use super::latest_for;

/// One balance per account — the set `position` actually consumes.
pub fn latest_each(balances: &[AccountBalance]) -> Vec<AccountBalance> {
    let mut ids: Vec<&str> = balances.iter().map(|b| b.account.as_str()).collect();
    ids.sort();
    ids.dedup();
    ids.iter().filter_map(|id| latest_for(balances, id).cloned()).collect()
}
